import{_ as t,o,c as i,a3 as a,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/verwaltung-werkzeuge-transaktionsprotokoll-aktivieren.png",l="/bilder/schueler/verwaltung-werkzeuge-transaktionsprotokoll-ist-aktiviert.png",w=JSON.parse('{"title":"Fehler von Gruppenprozessen im Transaktionsprotokoll prüfen","description":"","frontmatter":{"title":"Fehler von Gruppenprozessen im Transaktionsprotokoll prüfen","source_pageid":917,"source_revision":5297},"headers":[],"relativePath":"schild3/schueler/transaktionsprotokoll-verwenden-verwaltung-werkzeuge.md","filePath":"schild3/schueler/transaktionsprotokoll-verwenden-verwaltung-werkzeuge.md"}'),p={name:"schild3/schueler/transaktionsprotokoll-verwenden-verwaltung-werkzeuge.md"};function k(u,n,d,g,c,h){return o(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="fehler-von-gruppenprozessen-im-transaktionsprotokoll-prufen" tabindex="-1">Fehler von Gruppenprozessen im Transaktionsprotokoll prüfen <a class="header-anchor" href="#fehler-von-gruppenprozessen-im-transaktionsprotokoll-prufen" aria-label="Permalink to &quot;Fehler von Gruppenprozessen im Transaktionsprotokoll prüfen&quot;">​</a></h1><p>Aktivieren Sie bei der Fehlersuche das Transaktionsprotokoll, um intern abgefangene Datenbankfehler sichtbar zu machen.</p><p><a href="/bilder/schueler/verwaltung-werkzeuge-transaktionsprotokoll-aktivieren.png"><img src="'+s+'" alt="Aktivieren des Transaktionsprotokolls." loading="lazy"></a></p><p><em>Aktivieren des Transaktionsprotokolls.</em></p><p>Bei Gruppenprozessen werden i.d.R. SQL-Befehle an die Datenbank geschickt.</p><p>Wenn die aus irgendeinem Grunde nicht erfolgreich ausgeführt werden können, z.B. wegen eines defekten Index, so wird die Fehlermeldung intern abgefangen, damit der Benutzer nicht zahlreiche einzelne Fehlermeldungen erhält.</p><p>Wenn ein Gruppenprozess scheinbar nichts tut, prüfen Sie zuerst <strong>Filter, Markierungen, Bearbeitungsauswahl, Zielabschnitt und Optionen</strong>. Stimmen diese, kann das Transaktionsprotokoll intern abgefangene Datenbankfehler sichtbar machen.</p><p>Wurde das &quot;<em>Transaktionsprotokoll</em> über <em>Verwaltung ➜ Werkzeuge ➜ Transaktionsprotokoll verwenden ➜</em> <strong>Transaktionsprotokoll aktivieren</strong>&quot; eingeschaltet, werden diese Fehlermeldungen intern gespeichert und können über &quot;Transaktionsprotokoll zeigen&quot; sichtbar gemacht werden.</p><p><a href="/bilder/schueler/verwaltung-werkzeuge-transaktionsprotokoll-ist-aktiviert.png"><img src="'+l+'" alt="Hier wurde das Protokoll aktiviert." loading="lazy"></a></p><p><em>Hier wurde das Protokoll aktiviert.</em></p><p>Dass das Transaktionsprotokoll aktiviert wurde, ist daran ersichtlich, dass vor <em>Transaktionsprotokoll</em> nun ein &quot;<strong>+</strong>&quot; steht.</p><p>Weiterhin wird nun <em>Transaktionsprotokoll zeigen</em> zur Verfügung gestellt, in dem nun eventuell erzeugte Fehler abgelegt werden.</p>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,'Bei einem Aufruf von "Transaktionsprotokoll zeigen", wird anschließend das Transaktionsprotokoll automatisch gelöscht, damit der Speicher nicht irgendwann überläuft.'),e("p",null,"Ein Protokoll kann nur einmal angezeigt werden. Wenn Sie es später erneut benötigen, speichern Sie es vor dem Schließen separat aus dem Protokollfenster."),e("p",null,"Es kann bei einem reprodzierbar auftretenden Fehler über diesen ein neues Protokoll erzeugt werden.")],-1),e("p",null,"Soll ein weiteres Transaktionsprotokoll erzeugt werden, muss die Protokollierung erneut aktiviert werden.",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Transaktionsprotokoll_verwenden_(Verwaltung_Werkzeuge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 5297.")],-1)])])}const v=t(p,[["render",k]]);export{w as __pageData,v as default};
